-- 1. Create the new `tributes` table (for static, admin-curated content)
CREATE TABLE IF NOT EXISTS tributes (
  id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
  author_name TEXT NOT NULL,
  author_relationship TEXT,
  title TEXT,
  message TEXT NOT NULL,
  photo_url TEXT,
  sort_order INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE DEFAULT timezone('utc'::text, now()) NOT NULL
);

-- 2. Set up Row Level Security (RLS) for tributes
ALTER TABLE tributes ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Public can view tributes" 
  ON tributes FOR SELECT 
  USING (true);

CREATE POLICY "Admins have full access to tributes" 
  ON tributes FOR ALL 
  USING (
    auth.role() = 'authenticated'
  );

-- 3. Delete the previously seeded tributes from the `memories` table (if they exist)
DELETE FROM memories WHERE author_name IN ('Adebimpe Akerele', 'Dipo Kayode John', 'Atinuke A. Awoniyi', 'Adesewa Adeleke', 'Oluwadamilola John', 'Daughter-in-law');

-- 4. Clear the tributes table just in case of multiple runs
DELETE FROM tributes;

-- 5. Seed the Tributes table with the 6 original tributes from the PDF
INSERT INTO tributes (author_name, author_relationship, title, message, sort_order) VALUES
('Adebimpe Akerele', 'Daughter', null, '"To me, you were not only a father but someone I deeply loved and admired. Your unwavering faith, wisdom, kindness, and selfless love have shaped my life in countless ways. You taught us that true greatness is found in faith, humility, service, and love. Although you have departed this earthly home, your values and sacrifices continue to inspire us every day. Thank you for being our strength, our guide, and our greatest example. I will love and miss you always. Rest peacefully, Daddy."', 1),

('Dipo Kayode John', 'Son', null, 'Daddy, your life was a magnificent testimony of unwavering faith, absolute integrity, quiet resilience, and unconditional love. As the pillar of our family, you led us with profound wisdom, deep humility, and a gentle strength that commanded respect without ever demanding it. You lived your life selflessly, always placing God first, your family second, and the needs of others entirely before your own. You possessed a rare and beautiful gift: you truly believed in people. You looked at each of us and saw potential that we often failed to see in ourselves. You encouraged us to dream boldly, to reach higher, and to walk through life with courage. Your support was an anchor; you never stopped lifting up those around you, offering a listening ear, a guiding word, or a helping hand to anyone in need. The ripple effect of your kindness has touched countless lives far beyond our family circle, leaving an indelible mark on your community. Your legacy is not written in stone, but in the lives of the people you transformed and the enduring values you so carefully instilled in us. You taught us how to love without conditions, how to stand firm in the face of adversity, and how to walk uprightly before God. Though our hearts ache with a deep, consuming sorrow in your absence, we do not mourn as those without hope. We find immense comfort and rejoice knowing that you have finished your race beautifully and have gone to be forever with the Lord. Thank you, Daddy, for being an extraordinary father, a doting grandfather, an inspirational mentor, and a loyal friend. Your life was a blessing, your memory is a treasure, and you are loved beyond words. Rest well in perfect peace, Daddy JOK John, until we meet at the feet of Jesus to part no more. With everlasting love and gratitude,', 2),

('Atinuke A. Awoniyi', 'Daughter', null, 'So rare was a dad like you. My father is one of the most important people in my life, and I am forever grateful for everything he has done for me. He has been there through the good times and the difficult ones, always doing his best to guide me, support me, and help me become the person I am today. Your loving smile and gentle laugh can not be forgotten. In you there was no equal. My father has taught me lessons that I will carry with me for the rest of my life. Through his words, actions, and sacrifices, he has shown me the importance of strength, hard work, love, and perseverance. I may not always say it, but I truly appreciate everything you have done for me. Your love and guidance have made a difference in my life in ways I cannot fully explain. I am proud to call you my father. Thank you for every sacrifice, every lesson, every word of encouragement, and every moment you’ve been there for me. I will always carry on with the lessons you have taught me to love unconditionally, to give without looking back, to care without expecting reciprocation, to pray without ceasing, and above all to serve God which is the ultimate goal. I am happy because you know God, you serve God to the best of my knowledge and I know heaven has gained a beloved one. May you continue to rest in the bosom of the Lord your God. I love you Dad, and I am grateful to have you in my life.', 3),

('Adesewa Adeleke', 'Daughter', 'A Reflection on the Life of My Beloved Father', 'I honour the life of my beloved father, a man of hope, strength, wisdom, humility, and quiet dignity. My father was an intelligent and skilful man. I am proud to have inherited some of his passion, determination, and hardworking spirit. Baba Sewa always encouraged me and believed in me. One thing I will always cherish was his humility. Whenever I spoke to him about any family matter, he would simply say, “I will do whatever you say.” Those words reflected his deep love for his family and his desire to keep peace among us. Another quality that made him special was that he never wanted to be a burden to anyone. He always tried to solve his own problems and lived with dignity, independence, and contentment. Like every family, we had our challenges, but by God’s grace, we settled our misunderstandings and remained united. Although his passing came unexpectedly, I am thankful that we shared love, peace, and forgiveness before he left us. Dad, thank you for your love, guidance, and words of encouragement. Thank you for the values you instilled in us and the example you set through your life. Your memory will always remain in our hearts, and your legacy of love, humility, and integrity will continue through us. Sleep well, dear Dad. May your gentle soul rest in perfect peace. Baba Sewa, you will always be loved, remembered, and deeply missed.', 4),

('Oluwadamilola John', 'Son', 'Tribute to My Dad Oluwadamilola John', 'I''m not only mourning the passing of my father but also to celebrate a life that touched so many hearts. Writing this is one of the hardest things I have ever had to do because words can never fully express what my dad meant to me. Dad, you were more than a father, you were my guide, my protector, my friend, and my confidant. You trusted me, believed in me, and gave me responsibilities that made me stronger. Your strength gave me confidence, your wisdom guided my decisions, and your love held us all together. You taught me the values of hard work, wisdom, resilience, perseverance, tolerance, consistency, and kindness. Those lessons will remain with me for the rest of my life. You lived a life of sacrifice, always putting others before yourself. You worked tirelessly to become a better man and to leave a positive mark wherever you went. Even during difficult times, you remained steadfast, believing that every challenge could be overcome with faith, patience, and determination. Your smile could brighten a room, your advice could calm an anxious heart, and your presence was always reassuring. Though you are no longer with us physically, your voice, your values, and your legacy will continue to live in my heart. The pain of losing you is immense, but I am comforted by the memories we shared and the remarkable life you lived. I thank God for the privilege of calling you my father. Although your journey on earth has ended, your impact on my life will never fade. Dad, thank you for every sacrifice you made, every prayer you prayed for me, every lesson you taught me, and every expression of love you showed. I am proud to be your child, and I promise to honour your memory by living according to the values you instilled in me. As I say goodbye today, I do so with a heavy heart, but also with deep gratitude. Thank you for being an amazing father, a very accommodating and compassionate man, a caring grandfather, a dependable friend, and a blessing to everyone who had the privilege of knowing you. One thing that gives me comfort is knowing that you always said you never wanted to become a burden to any of your children in your old age. You never wanted us to watch you become helpless or vulnerable. By God''s grace, your wish was fulfilled. You remained a man of dignity and strength until the very end. While I would have loved to have you with us for many more years, I find peace in knowing that you departed with your honour and dignity intact. Dad, I will miss our conversations, your guidance, your encouragement, and the confidence you always had in me. Thank you for believing in me, even when I doubted myself. Your trust and mistakes inspired me to become a better son, a better father, and a better man. Rest peacefully, Dad. You fought the good fight, you finished your race, and you have left footprints that time can never erase. I love you deeply, I miss you dearly, and I will carry you in my heart forever. Though you are no longer by my side, you will always live on in my heart, in my thoughts, and in the values you passed on to me. Your memory will continue to inspire me every day of my life. Until we meet again, may your gentle soul rest in perfect peace. Amen.', 5),

('Daughter-in-law', 'Daughter-in-law', 'A Tribute to My Father-in-Law (Baba mi)', 'Daddy, although you are no longer with us, you have left a remarkable legacy of dignity, wisdom, and love. Words cannot fully express the sadness we feel at your passing, but they can express the deep gratitude I have for having known you. From the very beginning, you welcomed me into your family with love, kindness, and acceptance. For that, I will always be grateful. I will forever cherish your guidance, wise advice, and prayers. The values you lived by, your humility, and your quiet sacrifices will never be forgotten. Your life was a blessing to everyone who knew you, and your example will continue to inspire us. Though we miss you deeply, we take comfort in the beautiful memories you have left behind. You will always be remembered with love and gratitude. May your gentle soul rest in perfect peace.', 6);
